  "plans.priceNote": "आवश्यक शुल्क $14.99/माह और लागू कर, यदि कोई हो, है। व्यवसाय $29.99/माह और लागू कर, यदि कोई हो, है। कोई भी आवश्यक कर प्रदाता चेकआउट के दौरान निर्धारित किया जाता है और भुगतान से पहले अंतिम कुल में प्रदर्शित होना चाहिए। यह तुलना पृष्ठ कोई कर उद्धरण या भुगतान प्राधिकरण नहीं है।",
  "plans.mobilePriceNote": "केवल-मोबाइल योजना अपने इच्छित यू.एस। आधार मूल्य पर $4.99/माह है। App Store या Google Play खरीदारी से पहले वास्तविक स्थानीय सदस्यता मूल्य और किसी भी लागू कर को दर्शाता है। इसके उत्पाद, साइट और स्टाफ भत्ते लॉन्च के समय वेबसाइट स्तरों से अलग निर्धारित किए जाते हैं।",
  "plans.planChangeNote": "वेबसाइट योजना में बदलाव की पुष्टि बिलिंग प्रदाता द्वारा की जानी चाहिए। परिवर्तन अधिकृत होने से पहले नई कीमत, प्रभावी तिथि और किसी भी अनुपात की व्याख्या की जाएगी। अपग्रेड से दूसरी सदस्यता नहीं बननी चाहिए।",
