  "upgrade.trialHistoryNote": "यदि आप आवश्यक वस्तुओं के लिए भुगतान कर रहे हैं और व्यवसाय की ओर बढ़ रहे हैं, तो आप वही ग्राहक खाता और परीक्षण इतिहास रखते हैं। व्यवसाय में अतिरिक्त सात दिवसीय परीक्षण शामिल नहीं है। यदि आप अपग्रेड करते हैं जबकि आपका मूल परीक्षण अभी भी चल रहा है, तो इसकी मूल समाप्ति तिथि रीसेट नहीं होती है।",
