  "upgrade.chargedThroughProviderNote": "योजना परिवर्तन का शुल्क बिलिंग प्रदाता के माध्यम से लिया जाता है। आप अपनी वर्तमान योजना के अंतर्गत सदस्यता रद्द करें बटन का उपयोग करके या सेटिंग्स से इस पृष्ठ से अपनी सदस्यता रद्द कर सकते हैं। रद्द करने से आपकी भुगतान अवधि के अंत में भविष्य के नवीनीकरण रुक जाते हैं; यह कभी भी आपकी पहुँच को एक बार में समाप्त नहीं करता है। इन विकल्पों को देखने पर मौजूदा मानार्थ कार्यस्थानों से शुल्क नहीं लिया जाता है।",
  "billing.cancel.title": "सदस्यता रद्द करें",
  "billing.cancel.description": "{plan} से सदस्यता समाप्त करें। रद्द करने से आपकी भुगतान अवधि के अंत में भविष्य के नवीनीकरण रुक जाते हैं — यह कभी भी आपकी पहुँच को तुरंत समाप्त नहीं करता है।",
  "billing.cancel.yourPlan": "तुम्हारी योजना",
  "billing.cancel.doneTitle": "आपकी सदस्यता रद्द कर दी गई है।",
  "billing.cancel.doneWithEnd": "आप {endDate} तक पूर्ण पहुँच रखते हैं। उस तिथि के बाद आपके पास {graceDays}-दिन की केवल पढ़ने योग्य छूट अवधि है — आप अभी भी लॉग इन कर सकते हैं और अपने उत्पाद देख सकते हैं, लेकिन आप कुछ भी जोड़, संपादित, हटा, स्कैन, आयात, निर्यात या बदल नहीं सकते हैं। {gracePart}",
  "billing.cancel.graceEndsOn": "{date} पर 15 दिन की छूट अवधि समाप्त होने के बाद, आपका खाता और उसकी सभी जानकारी स्थायी रूप से हटा दी जाती है और उसे पुनर्प्राप्त नहीं किया जा सकता है।",
  "billing.cancel.doneNoEnd": "आप अपनी भुगतान अवधि के अंत तक पूर्ण पहुँच बनाए रखते हैं। उसके बाद, 15 दिन की केवल पढ़ने योग्य छूट अवधि लागू होती है। {wipeSentence}",
  "billing.cancel.refundWindowOpen": "आपने अपने पहले भुगतान शुल्क के 3 दिनों के भीतर रद्द कर दिया है, इसलिए आप उस पहले भुगतान की धनवापसी के पात्र हो सकते हैं। रद्द करने से रिफंड स्वयं जारी नहीं होता है — इसे {contact} के माध्यम से अनुरोध करें।",
  "billing.cancel.refundWindowClosed": "रद्द करने से अपने आप कोई धन-वापसी जारी नहीं हो जाती। {contact} के माध्यम से अनुरोध किए गए पहले सफल भुगतान शुल्क के केवल 3 दिनों के भीतर ही रिफंड लागू होता है।",
  "billing.cancel.notCanceledTitle": "आपकी सदस्यता रद्द नहीं की गई थी।",
  "billing.cancel.contactCode": "यदि आप {contact} से संपर्क करते हैं, तो इस कोड का उल्लेख करें: {code}",
  "billing.cancel.alreadyCanceledTitle": "यह सदस्यता पहले ही रद्द कर दी गई है।",
  "billing.cancel.alreadyCanceledWithEnd": "यह {date} पर समाप्त होता है। आप तब तक पूरी पहुँच बनाए रखें। उस तिथि के बाद आपके पास अपने उत्पादों को देखने के लिए {graceDays}-दिन की केवल पढ़ने योग्य छूट अवधि है। {wipeSentence}",
  "billing.cancel.alreadyCanceledNoEnd": "यह वर्तमान भुगतान अवधि के अंत में समाप्त होता है। आप तब तक पूरी पहुँच बनाए रखें।",
  "billing.cancel.appStoreNote": "यदि आपने कभी Google Play या Apple App Store के माध्यम से सदस्यता ली है, तो आपको उस स्टोर की सदस्यता सेटिंग्स के माध्यम से इसे रद्द करने की आवश्यकता हो सकती है। यह डायलॉग ऐप-स्टोर बिलिंग को नहीं रोक सकता। ऐप को अनइंस्टॉल करने या अपना StockHaven खाता हटाने से स्टोर सदस्यता रद्द नहीं होती है।",
