  "billing.readiness.environmentIncomplete": "Stripe चेकआउट क्रेडेंशियल, वेबहुक सत्यापन या ऐप रिटर्न पता सभी की पुष्टि नहीं की जा सकी। कोई चेकआउट प्रारंभ नहीं हो सकता।",
  "billing.readiness.ownerHasHistory": "इस स्वामी के पास पूर्व सदस्यता या परीक्षण साक्ष्य है। दूसरा चेकआउट नहीं बनाया जाना चाहिए।",
  "billing.readiness.trialAlreadyUsed": "एक परिचयात्मक परीक्षण पहले ही उपयोग किया जा चुका है या आरक्षित किया जा चुका है। कोई पुनरावर्ती परीक्षण प्रारंभ नहीं हो सकता।",
