  "billing.readiness.testModeUnverified": "खाता रिकॉर्ड पढ़ने योग्य हैं, लेकिन सुरक्षित Stripe परीक्षण-मोड रोकथाम और भुगतान-नवीकरण पूर्ति सत्यापित नहीं हैं। चेकआउट अवरुद्ध रहता है।",
  "billing.readiness.entitlementNotUnique": "मौजूदा योजना की जानकारी अनुपलब्ध या अस्पष्ट है। कोई चेकआउट प्रारंभ नहीं हो सकता।",
  "billing.readiness.accountBillingIncomplete": "खाता बिलिंग इतिहास पूरा नहीं पढ़ा जा सका। कोई चेकआउट प्रारंभ नहीं हो सकता।",
  "billing.readiness.billingHistoryIncomplete": "संपूर्ण स्वामी इतिहास सत्यापित नहीं किया जा सका। कोई चेकआउट प्रारंभ नहीं हो सकता।",
