  "print.pickCustomerOrderHint": "दस्तावेज़ का पूर्वावलोकन करने के लिए सूची से ग्राहक का ऑर्डर चुनें।",
  "print.pickReturnHint": "दस्तावेज़ का पूर्वावलोकन करने के लिए सूची से लॉग किया गया रिटर्न चुनें।",
  "print.chooseStyleHint": "एक शैली चुनें, फिर सूची से उत्पाद चुनें। पूर्वावलोकन वही दिखाता है जो प्रिंटर से निकलता है।",
  "print.howToReach": "अपने प्रिंटर तक कैसे पहुँचें",
  "print.howIntro": "यह ऐप आपके पास पहले से मौजूद प्रिंटर से कनेक्ट होता है — यह स्वयं प्रिंटर नहीं है। किसी एक तक पहुँचने के चार तरीके हैं, और उनमें से किसी एक के ऊपर दोनों योजनाओं पर लेबल प्रिंट होते हैं। पैकिंग पर्चियाँ, खरीद आदेश, आपूर्तिकर्ता दस्तावेज़ और रिपोर्टें केवल व्यवसाय के लिए हैं, चाहे उनका संबंध कुछ भी हो।",
  "print.howBluetoothLead": "Bluetooth.",
  "print.howBluetoothBody": "इस पृष्ठ से, डेस्कटॉप Chrome या Edge पर और Android Chrome पर: अपना लेबल प्रिंटर चुनें और लेबल सीधे उस पर जाएँ। यह iOS Safari में काम नहीं करता है — iPhone पर, Bluetooth प्रिंटिंग मोबाइल ऐप के साथ आती है। एक प्रिंटर जो केवल Zebra ZPL या Brother की अपनी भाषा बोलता है, वह इस पृष्ठ द्वारा भेजे गए लेबल को नहीं समझेगा; इसे काम करने से पहले असली प्रिंटर से जाँचा जाता है।",
  "print.howWifiLead": "Wi-Fi.",
  "print.howWifiBody": "अपनी दुकान के Wi-Fi पर प्रिंटर स्थापित करें, फिर प्रिंट बटन का उपयोग करें — यह दुकान नेटवर्क पर, इस कंप्यूटर पर स्थापित प्रिंटर के माध्यम से प्रिंट करता है। iPhone पर, AirPrint अंतर्निहित है: उसी Wi-Fi पर एक AirPrint प्रिंटर बस प्रिंट शीट में दिखाई देता है, कोई कॉर्ड और किसी ऐप की आवश्यकता नहीं है, और ऐप को किसी AirPrint-विशिष्ट कोड की आवश्यकता नहीं है। प्रिंटर को AirPrint का समर्थन करना चाहिए (अधिकांश नए वाले करते हैं) और फ़ोन और प्रिंटर एक ही Wi-Fi पर होने चाहिए।",
  "print.howEthernetLead": "ईथरनेट।",
  "print.howEthernetBody": "ईथरनेट कॉर्ड के साथ प्रिंटर को अपने शॉप नेटवर्क से तार दें, इसे कंप्यूटर पर इंस्टॉल करें, और प्रिंट बटन के माध्यम से प्रिंट करें। ईथरनेट एक डेस्कटॉप और कंप्यूटर पथ है — iPhones ईथरनेट कॉर्ड का उपयोग नहीं करते हैं।",
  "print.howUsbLead": "USB.",
  "print.howUsbBody": "प्रिंटर को उसके कॉर्ड के साथ कंप्यूटर में प्लग करें और प्रिंट बटन का उपयोग करें — यह वहाँ स्थापित प्रिंटर के माध्यम से प्रिंट करता है। USB OTG केबल वाले Android फोन पर, ऊपर दिया गया USB बटन सीधे प्रिंटर से बात करता है। iPhone सीधे USB पर प्रिंट नहीं कर सकता — वहाँ कोई WebUSB नहीं है — इसलिए मोबाइल ऐप से Wi-Fi / AirPrint, या Bluetooth का उपयोग करें।",
  "print.howCordsLead": "तार अभी भी iPhones की सेवा करते हैं, एक कदम हटा दिया गया है।",
  "print.howCordsBody": "दुकान के कंप्यूटर में प्लग किया गया एक USB प्रिंटर, या नेटवर्क से जुड़ा एक ईथरनेट प्रिंटर, दुकान के Wi-Fi (AirPrint / साझा प्रिंटर) पर आपके iPhone पर दिखाई देता है — तार प्रिंटर को नेटवर्क पर मजबूती से डालते हैं, और फोन वायरलेस तरीके से उस तक पहुँचता है।",
  "print.howOfflineLead": "अगर इंटरनेट बंद हो जाए,",
  "print.howOfflineBody": "इस पृष्ठ पर पहले से मौजूद लेबल और दस्तावेज़ अभी भी प्रिंट होते हैं — प्रिंट बटन, लेबल PDF, Bluetooth और USB को किसी कनेक्शन की आवश्यकता नहीं है। सबसे पहले पेज और उसके उत्पादों को लोड करने के लिए इंटरनेट की आवश्यकता होती है। पूर्ण ऑफ़लाइन मोड (बिना किसी कनेक्शन के ऐप में काम करना) एक अलग, बड़ा निर्माण है और यहाँ इसका दावा नहीं किया गया है।",
