  "settings.cancelTerms.appleLink": "Apple रद्दीकरण निर्देश",
  "settings.cancelTerms.googlePlayLink": "Google Play रद्दीकरण निर्देश",
  "settings.cancelTerms.graceTitle": "आपकी भुगतान अवधि समाप्त होने के बाद — 15 दिन की छूट, फिर विलोपन:",
  "settings.cancelTerms.intro": "ये सशुल्क Luminous StockHaven सदस्यता के लिए शर्तें हैं। वेबसाइट सदस्यता बिलिंग Stripe के माध्यम से होती है। आप नीचे दिए गए सदस्यता रद्द करें बटन का उपयोग करके किसी भी समय अपनी सदस्यता स्वयं रद्द कर सकते हैं — किसी कर्मचारी की मंजूरी की आवश्यकता नहीं है। रद्दीकरण और धनवापसी अनुरोधों को आधिकारिक ग्राहक सहायता संपर्क, theluminousbookshop@outlook.com के माध्यम से भी नियंत्रित किया जा सकता है।",
  "settings.cancelTerms.noApprovalBody": "आप किसी भी समय अपनी सदस्यता स्वयं रद्द कर सकते हैं। किसी कर्मचारी की मंजूरी की आवश्यकता नहीं है। बिलिंग प्रदाता द्वारा रद्दीकरण की पुष्टि करने के बाद ही भविष्य का नवीनीकरण रुकता है।",
  "settings.cancelTerms.noApprovalTitle": "बिना अनुमोदन के रद्द करें:",
  "settings.cancelTerms.paymentBody": "सशुल्क परीक्षणों के लिए, सात-दिवसीय परीक्षण के लिए साइनअप पर भुगतान विधि की आवश्यकता होती है। जब तक लागू परीक्षण रद्द करने की समय सीमा के भीतर रद्द नहीं किया जाता, चयनित मासिक योजना का शुल्क परीक्षण के बाद स्वचालित रूप से लिया जाएगा। साइनअप के दौरान कीमत, पहली बिलिंग तिथि और प्रदाता-विशिष्ट रद्दीकरण की समय सीमा दिखाई जानी चाहिए। ट्रायल बिलिंग Stripe के माध्यम से है।",
  "settings.cancelTerms.paymentTitle": "भुगतान विधि और स्वचालित नवीनीकरण:",
  "settings.cancelTerms.remainingBody": "यदि आपने बिलिंग अवधि के लिए पहले ही भुगतान कर दिया है, तो आप उस सत्यापित भुगतान तिथि तक पहुँच बनाए रख सकते हैं। पहले समाप्ति के लिए उपयुक्त प्रदाता की पुष्टि और किसी भी लागू रिफंड प्रबंधन की आवश्यकता होती है। नि:शुल्क-परीक्षण पहुँच प्रदाता द्वारा पुष्टि की गई परीक्षण समाप्ति तिथि के अनुसार समाप्त होती है।",
  "settings.cancelTerms.remainingTitle": "शेष पहुँच:",
  "settings.cancelTerms.storesBody": "यदि आपने कभी Google Play या Apple App Store के माध्यम से सदस्यता ली है, तो आपकी सदस्यता का बिल और प्रबंधन उस स्टोर द्वारा किया जाता है। आपको इसे सीधे उसी Google या Apple खाते के सदस्यता अनुभाग में रद्द करने की आवश्यकता हो सकती है जिसका उपयोग सदस्यता लेने के लिए किया गया था। एक अलग वेबसाइट सदस्यता रद्द करना, इस ऐप को अनइंस्टॉल करना, या Luminous StockHaven खाता हटाने का अनुरोध करना स्टोर-बिल सदस्यता को स्वचालित रूप से रद्द नहीं करता है। यह पुष्टि करने के लिए कि आपको बिल कौन देता है, अपनी खरीद रसीद की जाँच करें।",
  "settings.cancelTerms.storesTitle": "Google Play और Apple App Store सदस्यताएँ (यदि आपने कभी किसी स्टोर के माध्यम से सदस्यता ली है):",
  "settings.cancelTerms.title": "रद्दीकरण नियम एवं शर्तें",
  "settings.cancelTerms.trialBody": "सात दिवसीय परीक्षण का उपयोग प्रति पात्र ग्राहक केवल एक बार किया जा सकता है। किसी परीक्षण या सदस्यता को रद्द करने से दूसरा परीक्षण नहीं मिलता है; लौटने वाले ग्राहकों को सशुल्क सदस्यता चुननी होगी।",
  "settings.cancelTerms.trialTitle": "एक निःशुल्क परीक्षण:",
  "settings.canceled.endsOn": "यह सदस्यता रद्द कर दी गई है और {date} पर समाप्त हो गई है। आप तब तक पूरी पहुँच बनाए रखें।",
  "settings.delete.checking": "मौजूदा विलोपन अनुरोध की जाँच की जा रही है...",
  "settings.delete.description": "अपने Luminous StockHaven साइन-इन खाते को हटाने का अनुरोध करें।",
  "settings.delete.dialogDescription": "यह खाता हटाने की समीक्षा का अनुरोध करता है। यह आपके लॉगिन या इन्वेंट्री को तुरंत नहीं हटाता है, और यह किसी भी Stripe सदस्यता को रद्द नहीं करता है। यह पुष्टि करने के लिए कि आप अनुरोध सबमिट करना चाहते हैं, DELETE टाइप करें।",
